def _dependency_prefetch_guidance(self, project_path: str | None, question: str, *, limit: int = 20) -> dict[str, Any]:
        if not project_path:
            return {
                "available": 0,
                "missing": 0,
                "network_fetch_required": True,
                "recommended_prefetch": [],
                "agent_instruction": "Ask the user before prefetching dependency docs.",
            }
        metadata = self.service.read_project_metadata(project_path)
        deps = getattr(metadata, "dependencies", []) or []
        state = self.service._project_dependency_docs_state(metadata)
        unavailable = []
        if isinstance(state, dict):
            unavailable = [str(value) for value in [*(state.get("missing") or []), *(state.get("stale") or [])]]
        available = max(0, len(deps) - len(set(unavailable)))
        recommended = self._rank_dependencies_for_prefetch(deps, unavailable, question, limit=limit)
        return {
            "available": available,
            "missing": len(set(unavailable)),
            "network_fetch_required": bool(unavailable),
            "recommended_prefetch": recommended,
            "agent_instruction": "Ask the user before prefetching dependency docs. The user can approve prefetching all dependencies or only the recommended top-N.",
            "next_action": {
                "tool": "prepare_docs",
                "arguments_patch": {
                    "action": "prefetch_project_dependency_docs",
                    "project_path": project_path,
                    "include_packages": [item["library"] for item in recommended],
                    "include_flutter": False,
                },
            } if recommended else None,
        }

def _declared_authority_by_path(
    context_pack: Iterable[Mapping[str, Any]],
    *,
    project_path: str | None,
    target_paths: Iterable[str],
) -> dict[str, str]:
    values: dict[str, str] = {}
    for item in context_pack:
        if not isinstance(item, Mapping):
            continue
        path = str(item.get("path") or item.get("source") or "").strip().replace("\\", "/").casefold()
        authority = _effective_authority(
            dict(item), project_path=project_path, target_paths=target_paths,
        )
        if path and authority:
            values[path] = authority
    return values

def prepare_delivery_inventory(
    *, source: dict[str, Any], raw_text: str, query_plan: dict[str, Any],
    query_text: dict[str, str], eligible_query_ids: frozenset[str],
    requalify: Callable[..., dict[str, Any]],
) -> tuple[tuple[DeliveryUnit, ...], int | None]:
    """Build one verified unit inventory from the prepared current source window."""
    reference = source.get("_reference_evidence") or {}
    if not (
        isinstance(reference, dict)
        and reference.get("text") == raw_text
        and type(reference.get("char_start")) is int
    ):
        return (), None
    raw_start = int(reference["char_start"])
    prepared = {
        **source,
        "path_or_url": source.get("path") or source.get("source") or "",
        "_qualification_candidate": source.get("_qualification_candidate", source),
        "_independent_query_plan": query_plan,
        "_expected_project_identity": source.get("_expected_project_identity"),
        "_lifecycle_intent": source.get("_lifecycle_intent", "current"),
    }
    return (
        build_delivery_units(
            source=prepared,
            raw_text=raw_text,
            raw_start=raw_start,
            query_text=query_text,
            eligible_query_ids=eligible_query_ids,
            requalify=requalify,
