def _finish(payload: dict, snapshot: dict, retrieval: dict, root: str, budget: int):
    # Ordinary quality/capability primitives on private clones. The real handler
    # registers only the winning DTO, not these candidate drafts.
    from .docs_context_projection import _finalize_quality, _strip_legacy_locators
    p, b, r = deepcopy(payload), deepcopy(snapshot), deepcopy(retrieval)
    p["read_next"] = []
    b.pop("__read_next__", None)
    _strip_legacy_locators(p, b)
    _finalize_quality(r, p, b)
    if docs_context_budget_tokens(p) > budget:
        from .context_packet_labels import compact_section_labels
        p, b = compact_section_labels(p, b)
    if root:
        previous = payload.get("read_next") or []
        if previous:
            target = deepcopy(previous[0])
            source = (snapshot.get("__read_next__") or {}).get("source")
            if not isinstance(source, dict):
                return None
        else:
            target, source = prepare_docs_context_read_next(p, b, r, root=root)
        if target is not None and source is not None:
            visible = [(row["line_start"], row["line_end"]) for row in p["sources"]
                if row["path_or_url"] == target["path"]
                and row["project_identity"] == target["project_identity"]
                and (b[row["evidence_id"]]["source"].get("_source_snapshot_sha256") == target["snapshot_sha256"])]
            remaining = unread_lines(target["line_start"], target["line_end"], visible)
            if remaining:
                a, z = remaining[0]
                target = _read_next_row(root, source, line_start=a, line_end=z, reason=target["reason"])
            else:
                target = None
            if target is not None:
                if attach_docs_context_read_next(p, target, max_tokens=budget):
                    b["__read_next__"] = {"source": deepcopy(source)}
                elif previous:
                    # Unread obligations are not deleted to make a trial fit.
                    return None
        attach_source_continuation_locators(p, b, root=root, max_tokens=budget)
    _refresh_estimate(p)
    return p, b, r

def seed_envelopes(payload: dict, snapshot: dict) -> list[tuple[int, tuple]]:
    groups: dict[tuple, list] = {}
    for index, row in enumerate(payload.get("sources", [])):
        source = (snapshot.get(row.get("evidence_id")) or {}).get("source")
        if not isinstance(source, dict):
            continue
        raw = _verified_document(source, row)
        if raw is None:
            continue
        ref = source["_reference_evidence"]
        start = raw.find(row["snippet"], ref["char_start"], ref["char_end"])
        end = start + len(row["snippet"])
        parents = parse_markdown_parents(raw, ref["source"]["document_id"])
        if len(parents) > MAX_PARENT_SECTIONS:
            continue
        owner = next((p for p in parents if p.char_start <= start < end <= p.char_end), None)
        if owner is None:
            continue
        key = (row["project_identity"], row["path_or_url"], source.get("_source_snapshot_sha256"),
               source.get("_source_catalog_hash"), source.get("resolved_version"), owner.logical_id)
        groups.setdefault(key, []).append((index, row, source, raw, owner, start, end))
    result = []
    for rows in groups.values():
        if len(rows) < 2:
            continue
        index, row, source, raw, owner, _, _ = rows[0]
        if any(item[3] != raw for item in rows):
            continue
        atoms = [a for a in structural_spans(raw, owner.char_start, owner.char_end) if a[2] != "whitespace"]
        left, right = min(item[5] for item in rows), max(item[6] for item in rows)
        hits = [i for i, (a, z, _) in enumerate(atoms) if a < right and left < z]
        if not hits:
            continue
        start, end = min(left, atoms[hits[0]][0]), max(right, atoms[hits[-1]][1])
        bounds = [(start, end)]
        if hits[0] > 0 and atoms[hits[0] - 1][2] == "prose":
            bounds.append((atoms[hits[0] - 1][0], end))
        seen = {row["snippet"]}
        for a, z in bounds:
            proposal = _context_row(source, row, raw, owner, a, z, supplementary=False)
            if proposal is not None and proposal[0]["snippet"] not in seen:
                seen.add(proposal[0]["snippet"])
                result.append((index, (*proposal, "seed_envelope")))
    return result

